<?php if (!defined('ABSPATH')) { exit; } $slug = hsh_current_topic(); $topic = hsh_topics()[$slug]; $detail = hsh_topic_details()[$slug]; ?>
<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><?php hsh_document_head(); ?></head>
<body <?php body_class('hsh-home hsh-category hsh-category-'.$slug); ?>><?php wp_body_open(); ?><a class="hsh-skip" href="#hsh-main">本文へ移動</a>
<header class="hsh-header"><a class="hsh-brand" href="<?php echo esc_url(home_url('/')); ?>">ひろがる<span>趣味暮らし</span></a><nav aria-label="主要カテゴリー"><?php foreach(hsh_topics() as $key=>$t): ?><a <?php if($key===$slug){echo 'aria-current="page"';} ?> href="<?php echo esc_url(hsh_category_url($key)); ?>"><?php echo esc_html($t[0]); ?></a><?php endforeach; ?></nav></header>
<main id="hsh-main" class="hsh-main"><nav class="hsh-crumb" aria-label="パンくず"><a href="<?php echo esc_url(home_url('/')); ?>">トップ</a> / <?php echo esc_html($topic[0]); ?></nav><section class="hsh-category-intro"><p class="hsh-eyebrow"><?php echo esc_html($topic[2]); ?></p><h1><?php echo esc_html($topic[0]); ?></h1><h2><?php echo esc_html($detail[0]); ?></h2><p><?php echo esc_html($detail[1]); ?></p></section>
<?php $first = get_page_by_path($detail[2], OBJECT, 'post'); if($first && $first->post_status==='publish'): ?><section class="hsh-start"><span class="hsh-kicker">まずはこちらから</span><h2><?php echo esc_html($detail[3]); ?></h2><a href="<?php echo esc_url(get_permalink($first)); ?>"><?php echo esc_html(get_the_title($first)); ?> →</a></section><?php endif; ?>
<?php echo hsh_start_routes($slug); echo hsh_topic_reading_route($slug); ?><section class="hsh-articles"><h2>記事一覧</h2><div class="hsh-post-grid"><?php while(have_posts()): the_post(); ?><article><a href="<?php the_permalink(); ?>"><?php echo hsh_card_cover(get_post()); ?><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date('Y.m.d')); ?></time><h3><?php the_title(); ?></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),55)); ?></p><span class="hsh-read-more">記事を読む →</span></a></article><?php endwhile; ?></div><?php the_posts_pagination(array('prev_text'=>'前へ','next_text'=>'次へ')); ?></section>
<?php echo hsh_profile_markup(); echo hsh_search_markup('hsh-category-search'); ?></main>
<footer class="hsh-footer"><a href="<?php echo esc_url(home_url('/')); ?>">ひろがる趣味暮らし</a><nav aria-label="サイト情報"><a href="<?php echo esc_url(home_url('/hsh-about/')); ?>">プロフィール</a><a href="<?php echo esc_url(home_url('/hsh-editorial/')); ?>">記事・広告について</a><a href="<?php echo esc_url(home_url('/お問い合わせ/')); ?>">お問い合わせ</a><?php $policy=get_privacy_policy_url();if($policy): ?><a href="<?php echo esc_url($policy); ?>">プライバシーポリシー</a><?php endif; ?></nav><small>© <?php echo esc_html(wp_date('Y')); ?> ひろがる趣味暮らし</small></footer><?php wp_footer(); ?></body></html>
